53	
54	    /**
55	     * Maximum number of owners allowed in a single city. Creating an owner in a city that already
56	     * contains this many owners is rejected with {@link CityAtCapacityException}.
57	     */
58	    static final int MAX_OWNERS_PER_CITY = 50;
59	
60	    /**
61	     * Maximum number of owners that may be registered on a single day. Creating an owner on a day
62	     * that already has this many owners (counted by {@code registrationDate}) is rejected with
63	     * {@link DailyRegistrationLimitException}.
64	     */
65	    static final int MAX_OWNERS_PER_DAY = 100;
66	
67	    /**
68	     * Threshold of owners registered on a single day (counted by {@code registrationDate}) above
69	     * which a newly created owner is flagged with {@code bulkSignupWarning}. When more than this
70	     * many owners have already been created on that day, the new owner's warning is {@code true}.
71	     */
72	    static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
73	
74	    private final PetRepository petRepository;
