263	    @Override
264	    @Transactional
265	    public void saveOwner(Owner owner) throws DataAccessException {
266	        saveOwner(owner, false);
267	    }
268	
269	    /**
270	     * Save an owner, enforcing the create-time business rules.
271	     *
272	     * <p>The {@code sharesHousehold} flag is retained only for backward compatibility and is now a
273	     * no-op: it formerly bypassed a dedicated duplicate-household check, but duplicate detection is
274	     * now expressed solely through {@link #assertIdentityIsUnique(Owner)}, under which members of the
275	     * same household with different telephones are always allowed, so the flag has nothing to bypass.
276	     */
277	    @Override
278	    @Transactional
279	    public void saveOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
280	        boolean isCreate = owner.isNew();
281	        assertIdentityIsUnique(owner);
282	        if (owner.isNew()) {
283	            assertCityHasCapacity(owner);
284	        }
285	        if (owner.getRegistrationDate() == null) {
286	            owner.setRegistrationDate(LocalDate.now());
287	        }
288	        assertRegistrationDateNotInFuture(owner);
289	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
290	        if (owner.isNew()) {
291	            assertDailyRegistrationLimit(owner);
292	            owner.setBulkSignupWarning(computeBulkSignupWarning(owner));
293	        }
294	        if (owner.isNew() && owner.getCustomerCode() == null) {
295	            owner.setCustomerCode(generateCustomerCode(owner));
296	        }
297	        if (owner.isNew() && owner.getNamesakeCount() == null) {
298	            owner.setNamesakeCount(countNamesakes(owner));
299	        }
300	        if (owner.isNew()) {
301	            assignPossibleDuplicate(owner);
302	        }
303	        ownerRepository.save(owner);
304	        if (isCreate) {
305	            AUDIT.info("owner created id={} customerCode={} registrationDate={}",
306	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
307	        }
308	    }
309	
310	    /**
311	     * Count the existing owners that, at the moment this owner is created, share its first name
312	     * and last name (both compared case-insensitively). The owner being saved is excluded by id so
313	     * it never counts itself. This value is deterministic given the current data, so it is computed
314	     * once at creation time and stored.
315	     */
316	    private Integer countNamesakes(Owner owner) {
317	        String firstName = owner.getFirstName();
318	        String lastName = owner.getLastName();
319	        if (firstName == null || lastName == null) {
320	            return 0;
321	        }
322	        return (int) ownerRepository.findAll().stream()
323	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
324	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
325	                && lastName.equalsIgnoreCase(existing.getLastName()))
326	            .count();
327	    }
328	
329	    /**
330	     * Build an owner's {@code customerCode} formatted {@code '<REGION>-<HASH8>'}, where {@code REGION}
331	     * is the region code derived from the owner's postcode (or {@code 'UNKNOWN'} when no region can be
332	     * derived) and {@code HASH8} is the first eight upper-cased hex characters of SHA-256 over the
333	     * owner's normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The
334	     * value is deterministic in those fields and carries no sequence number (see
335	     * {@link Owner#customerCode(String, String, String)}).
336	     */
337	    private String generateCustomerCode(Owner owner) {
338	        return Owner.customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName());
339	    }
340	
341	    /**
342	     * Flag a newly created owner as a possible (soft) duplicate of an existing owner. A hard
343	     * duplicate (an owner reusing an existing normalized telephone) has already been rejected by
344	     * {@link #assertIdentityIsUnique(Owner)} before this runs, so this detects the weaker overlap: an
345	     * existing owner that shares this owner's last name (compared case-insensitively with collapsed
346	     * whitespace, see {@link Owner#normalizeHousehold(String)}) and postcode but has a <em>different</em>
347	     * normalized telephone. When such an owner exists, {@code possibleDuplicate} is set {@code true} and
348	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several match);
349	     * otherwise {@code possibleDuplicate} is set {@code false} and {@code possibleDuplicateOf} left unset.
350	     */
351	    private void assignPossibleDuplicate(Owner owner) {
352	        String lastName = Owner.normalizeHousehold(owner.getLastName());
353	        String postcode = owner.getPostcode();
354	        String normalizedTelephone = Owner.normalizeTelephone(owner.getTelephone());
355	        Integer match = null;
356	        if (lastName != null && postcode != null) {
357	            match = ownerRepository.findAll().stream()
358	                .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
359	                .filter(existing -> lastName.equals(Owner.normalizeHousehold(existing.getLastName())))
360	                .filter(existing -> postcode.equals(existing.getPostcode()))
361	                .filter(existing -> !Objects.equals(normalizedTelephone,
362	                    Owner.normalizeTelephone(existing.getTelephone())))
363	                .map(Owner::getId)
364	                .filter(Objects::nonNull)
365	                .min(Integer::compareTo)
366	                .orElse(null);
367	        }
368	        owner.setPossibleDuplicate(match != null);
369	        owner.setPossibleDuplicateOf(match);
370	    }
371	
372	    /**
373	     * Enforce that no <em>other</em> owner already shares this owner's derived identity, throwing
374	     * {@link DuplicateIdentityException} if one does. This single check consolidates the former
375	     * separate telephone, email and household duplicate checks into the one {@code identityKey}
376	     * (normalized telephone, normalized email (or empty) and household id, see
377	     * {@link Owner#identityKey(String, String, String, String)}).
378	     *
379	     * <p>Because the telephone is part of the key, two owners can only ever collide on the whole
380	     * key when their normalized telephones already match; the normalized telephone is therefore the
381	     * decisive component and is what this check compares. Consequently two members of the same
382	     * household with different telephones have different identity keys and are both allowed, while
383	     * an owner reusing an existing normalized telephone is rejected. The owner being saved is
384	     * excluded by id so updating an owner in place never conflicts with itself.
385	     */
386	    private void assertIdentityIsUnique(Owner owner) {
387	        String normalizedTelephone = Owner.normalizeTelephone(owner.getTelephone());
388	        if (normalizedTelephone == null) {
389	            return;
390	        }
391	        boolean duplicate = ownerRepository.findAll().stream()
392	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
393	            .map(existing -> Owner.normalizeTelephone(existing.getTelephone()))
394	            .anyMatch(normalizedTelephone::equals);
395	        if (duplicate) {
396	            throw new DuplicateIdentityException(Owner.identityKey(
397	                owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getAddress()));
398	        }
399	    }
400	
401	    /**
402	     * Enforce that the owner's city has not yet reached its capacity, throwing
403	     * {@link CityAtCapacityException} when the city (compared case-insensitively) already contains
404	     * {@link #MAX_OWNERS_PER_CITY} or more owners. The owner being saved is excluded by id.
405	     */
406	    private void assertCityHasCapacity(Owner owner) {
407	        String city = owner.getCity();
408	        if (city == null) {
409	            return;
410	        }
411	        long count = ownerRepository.findAll().stream()
412	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
413	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
414	            .count();
415	        if (count >= MAX_OWNERS_PER_CITY) {
416	            throw new CityAtCapacityException(city);
417	        }
418	    }
419	
420	    /**
421	     * Enforce that the owner's registration date is not later than the current server date, throwing
422	     * {@link FutureRegistrationDateException} when it is. A registration date may not be in the
423	     * future; a date defaulted to {@link LocalDate#now()} is never in the future, so this check is a
424	     * harmless no-op for that case.
425	     */
426	    private void assertRegistrationDateNotInFuture(Owner owner) {
427	        LocalDate registrationDate = owner.getRegistrationDate();
428	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
429	            throw new FutureRegistrationDateException(registrationDate);
430	        }
431	    }
432	
433	    /**
434	     * Roll a registration date forward to the next business day. A date that falls on a Saturday or
435	     * Sunday is advanced to the following Monday; a weekday is returned unchanged. This is applied to
436	     * the effective registration date (whether supplied in the request or defaulted to the server
437	     * date) so that every value derived from it&mdash;such as the membership number's year segment
438	     * and the daily create-limit counting&mdash;uses the adjusted business day.
439	     */
440	    private static LocalDate rollToBusinessDay(LocalDate date) {
441	        if (date == null) {
442	            return null;
443	        }
444	        DayOfWeek dayOfWeek = date.getDayOfWeek();
445	        if (dayOfWeek == DayOfWeek.SATURDAY) {
446	            return date.plusDays(2);
447	        }
448	        if (dayOfWeek == DayOfWeek.SUNDAY) {
449	            return date.plusDays(1);
450	        }
451	        return date;
452	    }
453	
454	    /**
455	     * Enforce that the owner's registration day has not yet reached its capacity, throwing
456	     * {@link DailyRegistrationLimitException} when {@link #MAX_OWNERS_PER_DAY} or more owners are
457	     * already registered on that day (counted by {@code registrationDate}). The owner being saved
458	     * is excluded by id.
459	     */
460	    private void assertDailyRegistrationLimit(Owner owner) {
461	        LocalDate registrationDate = owner.getRegistrationDate();
462	        if (registrationDate == null) {
463	            return;
464	        }
465	        long count = ownerRepository.findAll().stream()
466	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
467	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
468	            .count();
469	        if (count >= MAX_OWNERS_PER_DAY) {
470	            throw new DailyRegistrationLimitException(registrationDate);
471	        }
472	    }
473	
474	    /**
475	     * Compute whether a newly created owner should carry a bulk-signup warning, i.e. whether more
476	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created on this owner's
477	     * registration day (counted by {@code registrationDate}, excluding the owner being saved). Like
478	     * the daily-limit rule this reflects the state at creation time, so it is computed once and
479	     * stored on the owner.
480	     */
481	    private boolean computeBulkSignupWarning(Owner owner) {
482	        LocalDate registrationDate = owner.getRegistrationDate();
483	        if (registrationDate == null) {
484	            return false;
485	        }
486	        long count = ownerRepository.findAll().stream()
487	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
488	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
489	            .count();
490	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
491	    }
492	
493	    @Override
494	    @Transactional(readOnly = true)
495	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
496	        return ownerRepository.findByLastName(lastName);
497	    }
498	
499	    @Override
500	    @Transactional(readOnly = true)
501	    public Collection<Visit> findVisitsByPetId(int petId) {
502	        return visitRepository.findByPetId(petId);
503	    }
504	
505	    @Override
506	    @Transactional(readOnly = true)
507	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
508	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
509	    }
510	
511	    private <T> T findEntityById(Supplier<T> supplier) {
512	        try {
513	            return supplier.get();
514	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
515	            // Just ignore not found exceptions for Jdbc/Jpa realization
516	            return null;
517	        }
518	    }
519	
520	}
