183	    /**
184	     * Normalize an email to its canonical stored form, which is lower-cased. This is the single
185	     * source of truth for how an email is persisted, so inputs that differ only in letter case
186	     * are stored identically. Applied by {@link #setEmail(String)} so every persistence path
187	     * (create and update, mapper or hand-copied) stores the same canonical value.
188	     *
189	     * @param email the raw email, possibly {@code null}
190	     * @return the lower-cased form, or {@code null} if the input was {@code null}
191	     */
192	    public static String normalizeEmail(String email) {
193	        return email == null ? null : email.toLowerCase();
194	    }
195	
196	    /**
197	     * Normalize a telephone to its canonical E.164 stored form. This is the single source of
198	     * truth for how a telephone is compared and persisted, so inputs that differ only in
199	     * formatting (spaces, dashes, brackets) are treated as the same number.
200	     *
201	     * <p>The rules are:
202	     * <ul>
203	     *   <li>spaces, dashes and brackets are stripped;</li>
204	     *   <li>a leading {@code '+'} and its country code are kept as given;</li>
205	     *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
206	     *       is dropped from the national digits;</li>
207	     *   <li>the result must have 8 to 15 digits after the {@code '+'};</li>
208	     *   <li>for a recognized country code the national number (the digits after the country
209	     *       code) must have the length that code requires: {@code '+61'} requires 9 national
210	     *       digits and {@code '+1'} requires 10.</li>
211	     * </ul>
212	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}. Already-normalized
213	     * values are returned unchanged.
214	     *
215	     * @param telephone the raw telephone, possibly {@code null}
216	     * @return the E.164 form, or {@code null} if the input is {@code null} or cannot form a
217	     *     valid E.164 number
218	     */
219	    public static String normalizeTelephone(String telephone) {
220	        if (telephone == null) {
221	            return null;
222	        }
223	        String trimmed = telephone.trim();
224	        boolean hasCountryCode = trimmed.startsWith("+");
225	        // Strip spaces, dashes and brackets; a leading '+' (if any) is left in place.
226	        String stripped = trimmed.replaceAll("[\\s\\-()]", "");
227	        if (hasCountryCode) {
228	            stripped = stripped.substring(1);
229	        }
230	        if (!stripped.matches("\\d+")) {
231	            return null;
232	        }
233	        String digits;
234	        if (hasCountryCode) {
235	            digits = stripped;
236	        } else {
237	            if (stripped.startsWith("0")) {
238	                stripped = stripped.substring(1);
239	            }
240	            digits = "61" + stripped;
241	        }
242	        if (digits.length() < 8 || digits.length() > 15) {
243	            return null;
244	        }
245	        if (!hasValidNationalNumberLength(digits)) {
246	            return null;
247	        }
248	        return "+" + digits;
249	    }
250	
251	    /**
252	     * Required national-number length (the count of digits after the country code) for each
253	     * recognized country code, longest country code first so the prefix match is unambiguous.
254	     */
255	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = new LinkedHashMap<>();
256	    static {
257	        NATIONAL_NUMBER_LENGTHS.put("61", 9);
258	        NATIONAL_NUMBER_LENGTHS.put("1", 10);
259	    }
260	
261	    /**
262	     * Check that the national number of an E.164 digit string (no leading {@code '+'}) has the
263	     * length its country code requires. A country code with no registered length places no
264	     * additional constraint and is accepted.
265	     *
266	     * @param digits the E.164 digits without the leading {@code '+'}
267	     * @return {@code true} if the national-number length is valid for the country code
268	     */
269	    private static boolean hasValidNationalNumberLength(String digits) {
270	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
271	            String countryCode = entry.getKey();
272	            if (digits.startsWith(countryCode)) {
273	                return digits.length() - countryCode.length() == entry.getValue();
274	            }
275	        }
276	        return true;
277	    }
278	
279	    /**
280	     * Common street-type abbreviations expanded by {@link #normalizeAddress(String)}, keyed by the
281	     * upper-cased abbreviation.
282	     */
283	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
284	        "ST", "STREET",
285	        "RD", "ROAD",
286	        "AVE", "AVENUE");
287	
288	    /**
289	     * Normalize an address to its canonical stored form. Leading and trailing whitespace is
290	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
291	     * and common street-type abbreviations are expanded as whole words ({@code ST}->{@code STREET},
292	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). This is the single source of truth for
293	     * how an address is persisted and compared, so inputs that differ only in letter case, spacing
294	     * or abbreviation are treated as the same address. Applied by {@link #setAddress(String)} so
295	     * every persistence path (create and update, mapper or hand-copied) stores the same canonical
296	     * value. The transform is idempotent: a normalized address normalizes to itself.
297	     *
298	     * @param address the raw address, possibly {@code null}
299	     * @return the normalized form, or {@code null} if the input was {@code null}
300	     */
301	    public static String normalizeAddress(String address) {
302	        if (address == null) {
303	            return null;
304	        }
305	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
306	        if (collapsed.isEmpty()) {
307	            return collapsed;
308	        }
309	        String[] tokens = collapsed.split(" ");
310	        StringBuilder normalized = new StringBuilder(collapsed.length());
311	        for (int i = 0; i < tokens.length; i++) {
312	            if (i > 0) {
313	                normalized.append(' ');
314	            }
315	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
316	        }
317	        return normalized.toString();
318	    }
319	
320	    /**
321	     * Normalize a household field (such as last name or address) to its canonical form for
322	     * duplicate-household comparison. Leading and trailing whitespace is trimmed, internal runs
323	     * of whitespace are collapsed to a single space, and the result is lower-cased, so inputs
324	     * that differ only in letter case or spacing are treated as the same value.
325	     *
326	     * @param value the raw field value, possibly {@code null}
327	     * @return the normalized form, or {@code null} if the input was {@code null}
328	     */
329	    public static String normalizeHousehold(String value) {
330	        if (value == null) {
331	            return null;
332	        }
333	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
334	    }
335	
336	    /**
337	     * Compute the stable identifier shared by all owners in the same household, i.e. with the same
338	     * last name (compared case-insensitively with collapsed whitespace, see
339	     * {@link #normalizeHousehold(String)}) and the same normalized address (see
340	     * {@link #normalizeAddress(String)}). The value is deterministic in those two fields, so two
341	     * owners who share a household are assigned the same id. It is formatted {@code 'HH-<HEX12>'}
342	     * where {@code HEX12} is the first twelve upper-cased hex characters of the SHA-256 digest of
343	     * the normalized last name and address.
344	     *
345	     * @param lastName the owner's last name, possibly {@code null}
346	     * @param address the owner's address, possibly {@code null}
347	     * @return the household id, or {@code null} if either field is {@code null}
348	     */
349	    public static String householdId(String lastName, String address) {
350	        String normalizedLastName = normalizeHousehold(lastName);
351	        String normalizedAddress = normalizeAddress(address);
352	        if (normalizedLastName == null || normalizedAddress == null) {
353	            return null;
354	        }
355	        String key = normalizedLastName + "\n" + normalizedAddress;
356	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase();
357	    }
358	
359	    /**
360	     * Compute the full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}. This is the
361	     * shared primitive behind every hash-derived owner value (the household id and the customer code),
362	     * so they all agree on algorithm and encoding.
363	     *
364	     * @param value the string to digest, never {@code null}
365	     * @return the 64-character lower-case hex digest
366	     */
367	    private static String sha256Hex(String value) {
368	        try {
369	            byte[] digest = MessageDigest.getInstance("SHA-256")
370	                .digest(value.getBytes(StandardCharsets.UTF_8));
371	            StringBuilder hex = new StringBuilder(digest.length * 2);
372	            for (byte b : digest) {
373	                hex.append(String.format("%02x", b));
374	            }
375	            return hex.toString();
376	        } catch (NoSuchAlgorithmException e) {
377	            // SHA-256 is a standard algorithm required to be present on every JVM.
378	            throw new IllegalStateException("SHA-256 not available", e);
379	        }
380	    }
381	
382	    /**
383	     * Build an owner's {@code customerCode}, the stable owner identity assigned once when the owner is
384	     * created. It is formatted {@code '<REGION>-<HASH8>'} where:
385	     * <ul>
386	     *   <li>{@code REGION} is the region code derived from the postcode (see
387	     *       {@link #regionForPostcode(String)}), or {@code 'UNKNOWN'} when the postcode is absent or
388	     *       in no known range, and</li>
389	     *   <li>{@code HASH8} is the first eight upper-cased hex characters of the SHA-256 digest of the
390	     *       normalized telephone (see {@link #normalizeTelephone(String)}) concatenated with the last
391	     *       name.</li>
392	     * </ul>
393	     * The value is deterministic in the postcode, telephone and last name (e.g.
394	     * {@code 'NSW-1A2B3C4D'}); it carries no sequence number.
395	     *
396	     * @param postcode the owner's postcode, possibly {@code null}
397	     * @param telephone the owner's raw telephone, possibly {@code null}
398	     * @param lastName the owner's last name, possibly {@code null}
399	     * @return the customer code, or {@code null} if the telephone or last name is {@code null}
400	     */
401	    public static String customerCode(String postcode, String telephone, String lastName) {
402	        if (telephone == null || lastName == null) {
403	            return null;
404	        }
405	        String region = regionForPostcode(postcode);
406	        if (region == null) {
407	            region = "UNKNOWN";
408	        }
409	        String normalizedTelephone = normalizeTelephone(telephone);
410	        String key = (normalizedTelephone == null ? "" : normalizedTelephone) + lastName;
411	        return region + "-" + sha256Hex(key).substring(0, 8).toUpperCase();
412	    }
413	
414	    /**
415	     * Compute an owner's {@code identityKey}, the single derived value through which all
416	     * duplicate detection is now expressed. It consolidates the three formerly separate
417	     * telephone, email and household duplicate checks into one key, formatted as
418	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}:
419	     * <ul>
420	     *   <li>the normalized telephone (see {@link #normalizeTelephone(String)}),</li>
421	     *   <li>the normalized email (see {@link #normalizeEmail(String)}), or the empty string
422	     *       when no email is present, and</li>
423	     *   <li>the household id (see {@link #householdId(String, String)}).</li>
424	     * </ul>
425	     * A {@code null} component is rendered as the empty string. Two owners are the same identity
426	     * only when their <em>whole</em> keys are equal; because the telephone is part of the key, two
427	     * members of the same household with different telephones have different keys.
428	     *
429	     * @param telephone the owner's raw telephone, possibly {@code null}
430	     * @param email the owner's email, possibly {@code null}
431	     * @param lastName the owner's last name, possibly {@code null}
432	     * @param address the owner's address, possibly {@code null}
433	     * @return the identity key, never {@code null}
434	     */
435	    public static String identityKey(String telephone, String email, String lastName, String address) {
436	        String normalizedTelephone = normalizeTelephone(telephone);
437	        String normalizedEmail = normalizeEmail(email);
438	        String household = householdId(lastName, address);
439	        return (normalizedTelephone == null ? "" : normalizedTelephone)
440	            + "|" + (normalizedEmail == null ? "" : normalizedEmail)
441	            + "|" + (household == null ? "" : household);
442	    }
443	
444	    /**
445	     * Build an owner's {@code membershipNumber}, the stable membership identifier derived from the
446	     * owner's own persisted fields. It is formatted {@code '<customerCode>-M<YY>'} where {@code YY}
447	     * is the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}). The
448	     * value is deterministic in those two fields.
449	     *
450	     * @param customerCode the owner's customer code, possibly {@code null}
451	     * @param registrationDate the owner's registration date, possibly {@code null}
452	     * @return the membership number, or {@code null} if either field is {@code null}
453	     */
454	    public static String membershipNumber(String customerCode, LocalDate registrationDate) {
455	        if (customerCode == null || registrationDate == null) {
456	            return null;
457	        }
458	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
459	    }
460	
461	    /**
462	     * Build an owner's {@code membershipLevel}, the derived numeric level assigned on create. The
463	     * value starts at 1, gains 1 when an email is present and gains 1 when {@code namesakeCount} is 0,
464	     * and is capped at 3 (level 4 is reserved for tenure). The value is deterministic in those two
465	     * fields.
466	     *
467	     * @param namesakeCount the owner's namesake count, possibly {@code null}
468	     * @param email the owner's email, possibly {@code null}
469	     * @return the membership level, an integer from 1 to 3
470	     */
471	    public static int membershipLevel(Integer namesakeCount, String email) {
472	        int level = 1;
473	        if (email != null && !email.isEmpty()) {
474	            level++;
475	        }
476	        if (namesakeCount != null && namesakeCount == 0) {
477	            level++;
478	        }
479	        return Math.min(level, 3);
480	    }
481	
482	    /**
483	     * Fixed city-to-region table used by {@link #regionForCity(String)} to resolve a city's region
484	     * for postcode validation, keyed by the exact city name.
485	     */
486	    private static final Map<String, String> CITY_REGION = Map.of(
487	        "Sydney", "NSW",
488	        "Melbourne", "VIC",
489	        "Brisbane", "QLD");
490	
491	    /**
492	     * Derive an owner's {@code locality}, the canonical region for the owner, from the {@code REGION}
493	     * segment of the owner's {@code customerCode} (see {@link #customerCode(String, String, String)}).
494	     * Because the customer code's region is itself derived from the postcode, the locality now shares
495	     * the owner's region-and-hash identity: it is the text before the first {@code '-'} of the customer
496	     * code. When the owner has no customer code the locality is {@code 'UNKNOWN'}.
497	     *
498	     * @param customerCode the owner's customer code, possibly {@code null}
499	     * @return the canonical region string, or {@code 'UNKNOWN'} when no customer code is present
500	     */
501	    public static String locality(String customerCode) {
502	        if (customerCode == null) {
503	            return "UNKNOWN";
504	        }
505	        int dash = customerCode.indexOf('-');
506	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
507	    }
508	
509	    /**
510	     * Resolve the canonical region for a city from the fixed {@link #CITY_REGION} table. A city not
511	     * in the table (including {@code null}) resolves to {@code 'UNKNOWN'}.
512	     *
513	     * @param city the owner's city, possibly {@code null}
514	     * @return the matching region, or {@code 'UNKNOWN'} when the city is not in the table
515	     */
516	    private static String regionForCity(String city) {
517	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
518	    }
519	
520	    /**
521	     * Fixed region-to-postcode-range table used by {@link #isPostcodeValidForCity(String, String)}
522	     * and {@link #regionForPostcode(String)}, keyed by the canonical region. Each entry is the
523	     * inclusive low and high bound of the region's valid 4-digit postcodes
524	     * ({@code NSW} 2000-2099, {@code VIC} 3000-3099, {@code QLD} 4000-4099). A region not in this
525	     * table (including {@code 'UNKNOWN'}) places no range constraint.
526	     */
527	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
528	        "NSW", new int[] {2000, 2099},
529	        "VIC", new int[] {3000, 3099},
530	        "QLD", new int[] {4000, 4099});
531	
532	    /**
533	     * Resolve the canonical region whose postcode range contains the given postcode, using the fixed
534	     * {@link #REGION_POSTCODE_RANGES} table. A {@code null} postcode, one that is not exactly four
535	     * digits, or one that falls in no known range resolves to {@code null}.
536	     *
537	     * @param postcode the owner's postcode, possibly {@code null}
538	     * @return the matching region, or {@code null} when no range contains the postcode
539	     */
540	    private static String regionForPostcode(String postcode) {
541	        if (postcode == null || !postcode.matches("\\d{4}")) {
542	            return null;
543	        }
544	        int value = Integer.parseInt(postcode);
545	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
546	            int[] range = entry.getValue();
547	            if (value >= range[0] && value <= range[1]) {
548	                return entry.getKey();
549	            }
550	        }
551	        return null;
552	    }
553	
554	    /**
555	     * Check whether a postcode is valid for an owner's city. Postcode is optional, so a
556	     * {@code null} or empty postcode is always valid. When present it must be exactly four
557	     * digits, and when the city's region (from the fixed city-to-region table) has a known postcode
558	     * range the value must fall within that inclusive range. A city with no known region accepts
559	     * any four-digit postcode. This is the single source of
560	     * truth for postcode validity, shared by the DTO validation and any persistence path.
561	     *
562	     * @param postcode the owner's postcode, possibly {@code null}
563	     * @param city the owner's city, possibly {@code null}
564	     * @return {@code true} if the postcode is absent or valid for the city, {@code false} otherwise
565	     */
566	    public static boolean isPostcodeValidForCity(String postcode, String city) {
567	        if (postcode == null || postcode.isEmpty()) {
568	            return true;
569	        }
570	        if (!postcode.matches("\\d{4}")) {
571	            return false;
572	        }
573	        int[] range = REGION_POSTCODE_RANGES.get(regionForCity(city));
574	        if (range == null) {
575	            return true;
576	        }
577	        int value = Integer.parseInt(postcode);
578	        return value >= range[0] && value <= range[1];
579	    }
580	
581	    /**
582	     * Compute an owner's {@code checkDigit}, a single Luhn check digit (0-9) over the digits
583	     * contained in the {@code customerCode}. Non-digit characters in the code are ignored. The
584	     * value is deterministic in the customer code and is the standard Luhn check digit: each
585	     * digit is weighted right-to-left, every second digit (starting with the rightmost) is
586	     * doubled with digit sums above nine reduced by nine, and the check digit is the amount that
587	     * brings the weighted sum up to the next multiple of ten.
588	     *
589	     * @param customerCode the owner's customer code, possibly {@code null}
590	     * @return the Luhn check digit from 0 to 9, or {@code null} if the customer code is {@code null}
591	     */
592	    public static Integer checkDigit(String customerCode) {
593	        if (customerCode == null) {
594	            return null;
595	        }
596	        int sum = 0;
597	        boolean dbl = true;
598	        for (int i = customerCode.length() - 1; i >= 0; i--) {
599	            char c = customerCode.charAt(i);
600	            if (c < '0' || c > '9') {
601	                continue;
602	            }
603	            int d = c - '0';
604	            if (dbl) {
605	                d *= 2;
606	                if (d > 9) {
607	                    d -= 9;
608	                }
609	            }
610	            sum += d;
611	            dbl = !dbl;
612	        }
613	        return (10 - (sum % 10)) % 10;
614	    }
615	
616	    /**
617	     * Derive an owner's {@code contactPreference}, the preferred channel for contacting the owner.
618	     * The value is {@code 'EMAIL'} when an email is present and {@code 'PHONE'} otherwise. The value
619	     * is deterministic in the email.
620	     *
621	     * @param email the owner's email, possibly {@code null}
622	     * @return {@code 'EMAIL'} when an email is present, otherwise {@code 'PHONE'}
623	     */
624	    public static String contactPreference(String email) {
625	        return (email != null && !email.isEmpty()) ? "EMAIL" : "PHONE";
626	    }
627	
628	    /**
629	     * Derive an owner's {@code ageBand}, the band the owner's age falls into on the registration
630	     * date. The age in whole years is the number of completed years between {@code birthDate} and
631	     * {@code registrationDate}, and the band is {@code 'MINOR'} when under 18, {@code 'ADULT'} when
632	     * 18 to 64 inclusive, and {@code 'SENIOR'} when 65 or older. The value is deterministic in those
633	     * two fields and is only defined when both are present.
634	     *
635	     * @param birthDate the owner's date of birth, possibly {@code null}
636	     * @param registrationDate the owner's registration date, possibly {@code null}
637	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when either date
638	     *     is {@code null}
639	     */
640	    public static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
641	        if (birthDate == null || registrationDate == null) {
642	            return null;
643	        }
644	        int age = Period.between(birthDate, registrationDate).getYears();
645	        if (age < 18) {
646	            return "MINOR";
647	        }
648	        if (age < 65) {
649	            return "ADULT";
650	        }
651	        return "SENIOR";
652	    }
653	
654	    protected Set<Pet> getPetsInternal() {
655	        if (this.pets == null) {
656	            this.pets = new HashSet<>();
657	        }
658	        return this.pets;
659	    }
660	
661	    protected void setPetsInternal(Set<Pet> pets) {
662	        this.pets = pets;
663	    }
664	
665	    public List<Pet> getPets() {
666	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
667	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
668	        return Collections.unmodifiableList(sortedPets);
669	    }
670	
671	    public void setPets(List<Pet> pets) {
672	        this.pets = new HashSet<>(pets);
673	    }
674	
675	    public void addPet(Pet pet) {
676	        getPetsInternal().add(pet);
677	        pet.setOwner(this);
678	    }
679	
680	    /**
681	     * Return the Pet with the given name, or null if none found for this Owner.
682	     *
683	     * @param name to test
684	     * @return true if pet name is already in use
685	     */
686	    public Pet getPet(String name) {
687	        return getPet(name, false);
688	    }
689	
690	    /**
691	     * Return the Pet with the given name, or null if none found for this Owner.
692	     *
693	     * @param name to test
694	     * @return true if pet name is already in use
695	     */
696	    public Pet getPet(String name, boolean ignoreNew) {
697	        name = name.toLowerCase();
698	        for (Pet pet : getPetsInternal()) {
699	            if (!ignoreNew || !pet.isNew()) {
700	                String compName = pet.getName();
701	                compName = compName.toLowerCase();
702	                if (compName.equals(name)) {
703	                    return pet;
704	                }
705	            }
706	        }
707	        return null;
708	    }
709	
710	    public Pet getPet(Integer petId) {
711	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
712	    }
713	
714	    @Override
715	    public String toString() {
716	        return new ToStringCreator(this)
717	
718	            .append("id", this.getId())
719	            .append("new", this.isNew())
720	            .append("lastName", this.getLastName())
721	            .append("firstName", this.getFirstName())
722	            .append("address", this.address)
723	            .append("city", this.city)
724	            .append("telephone", this.telephone)
725	            .toString();
726	    }
727	}
