32	    @Mapping(target = "ageBand", expression = "java(formatAgeBand(owner))")
33	    @Mapping(target = "possibleDuplicate", expression = "java(formatPossibleDuplicate(owner))")
34	    OwnerDto toOwnerDto(Owner owner);
35	
36	    /** Format an owner's name as 'LastName, FirstName' from the stored names. */
37	    default String formatDisplayName(Owner owner) {
38	        if (owner == null) {
39	            return null;
40	        }
41	        return owner.getLastName() + ", " + owner.getFirstName();
42	    }
43	
44	    /**
45	     * Format an owner's initials as the upper-cased first letters of firstName and lastName,
46	     * dot-separated with a trailing dot (e.g. 'J.S.').
47	     */
48	    default String formatInitials(Owner owner) {
49	        if (owner == null) {
50	            return null;
51	        }
52	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
53	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
54	    }
55	
56	    /**
57	     * Compute the owner's household id, the stable identifier shared by all owners who live in the
58	     * same household (see {@link Owner#householdId(String, String)}).
59	     */
60	    default String formatHouseholdId(Owner owner) {
61	        if (owner == null) {
62	            return null;
63	        }
64	        return Owner.householdId(owner.getLastName(), owner.getAddress());
65	    }
66	
67	    /**
68	     * Compute the owner's membership number, the stable identifier derived from the owner's
69	     * customer code and registration date (see {@link Owner#membershipNumber(String, java.time.LocalDate)}).
70	     */
71	    default String formatMembershipNumber(Owner owner) {
72	        if (owner == null) {
73	            return null;
74	        }
75	        return Owner.membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate());
76	    }
77	
78	    /**
79	     * Compute the owner's membership level, the derived numeric level based on the owner's namesake
80	     * count and whether an email is present
81	     * (see {@link Owner#membershipLevel(Integer, String)}).
82	     */
83	    default Integer formatMembershipLevel(Owner owner) {
84	        if (owner == null) {
85	            return null;
86	        }
87	        return Owner.membershipLevel(owner.getNamesakeCount(), owner.getEmail());
88	    }
89	
90	    /**
91	     * Compute the owner's locality, the canonical region taken from the {@code REGION} segment of the
92	     * owner's customer code (see {@link Owner#locality(String)}).
93	     */
94	    default String formatLocality(Owner owner) {
95	        if (owner == null) {
96	            return null;
97	        }
98	        return Owner.locality(owner.getCustomerCode());
99	    }
100	
101	    /**
102	     * Resolve the owner's bulk-signup warning flag, treating a missing (null) stored value as
103	     * {@code false} so the response always carries an explicit boolean.
104	     */
105	    default Boolean formatBulkSignupWarning(Owner owner) {
106	        if (owner == null) {
107	            return null;
108	        }
109	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
110	    }
111	
112	    /**
113	     * Derive the owner's contact preference, {@code 'EMAIL'} when an email is present and
114	     * {@code 'PHONE'} otherwise (see {@link Owner#contactPreference(String)}).
115	     */
116	    default String formatContactPreference(Owner owner) {
117	        if (owner == null) {
118	            return null;
119	        }
120	        return Owner.contactPreference(owner.getEmail());
121	    }
122	
123	    /**
124	     * Compute the owner's identity key, the single derived value consolidating the telephone, email
125	     * and household duplicate checks (see
126	     * {@link Owner#identityKey(String, String, String, String)}).
127	     */
128	    default String formatIdentityKey(Owner owner) {
129	        if (owner == null) {
130	            return null;
131	        }
132	        return Owner.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getAddress());
133	    }
